from fastapi import FastAPI, Query, Header, Cookie
from pydantic import BaseModel, Field
from fastapi.testclient import TestClient

app = FastAPI()

class QueryModel(BaseModel):
    q_param: str = Field(..., alias="q-param")

@app.get("/")
async def root(params: QueryModel = Query()):
    return params

client = TestClient(app)

def test_query_alias():
    # This should work
    response = client.get("/?q-param=hello")
    print(f"Query alias response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"q_param": "hello"}

def test_query_name_error():
    # This should be a validation error, and 'q_param' should be in 'input'
    response = client.get("/?q_param=hello")
    print(f"Query name error response: {response.json()}")
    assert response.status_code == 422
    # The issue says: "the `input` field will not contain the extra parameter (passed by name)"
    # Let's check the error details.
    errors = response.json()["detail"]
    # We expect a missing field error for 'q-param' and an extra field error for 'q_param'
    # But if 'q_param' was added to processed_keys, it won't be seen as extra.
    print(f"Errors: {errors}")

def test_header_alias():
    class HeaderModel(BaseModel):
        h_param: str = Field(..., alias="h-param")

    @app.get("/header")
    async def header_root(params: HeaderModel = Header()):
        return params

    response = client.get("/header", headers={"h-param": "hello"})
    print(f"Header alias response: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"h_param": "hello"}

def test_header_name_error():
    class HeaderModel(BaseModel):
        h_param: str = Field(..., alias="h-param")

    @app.get("/header_err")
    async def header_err_root(params: HeaderModel = Header()):
        return params

    response = client.get("/header_err", headers={"h_param": "hello"})
    print(f"Header name error response: {response.json()}")
    assert response.status_code == 422
    print(f"Errors: {response.json()['detail']}")

if __name__ == "__main__":
    try:
        test_query_alias()
        print("test_query_alias passed")
    except Exception as e:
        print(f"test_query_alias failed: {e}")

    try:
        test_query_name_error()
        print("test_query_name_error passed")
    except Exception as e:
        print(f"test_query_name_error failed: {e}")

    try:
        test_header_alias()
        print("test_header_alias passed")
    except Exception as e:
        print(f"test_header_alias failed: {e}")

    try:
        test_header_name_error()
        print("test_header_name_error passed")
    except Exception as e:
        print(f"test_header_name_error failed: {e}")

